values('tcf-listening-06','tcf-listening-2026-11-test06-v2',$paper06v2${"id":"tcf-listening-06","version":"tcf-listening-2026-11-test06-v2","title":"TCF Listening · Test 06","seconds":2100,"questions":[{"number":1,"kind":"image","question":"Quelle action voit-on ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"La cliente examine les fruits disposés dans deux cagettes du marché.","transcript":"Question 1.\nRegardez l’image et écoutez les propositions.\nA. Une vendeuse étiquette des bocaux sur une étagère. B. Une cliente compare les fruits de deux paniers. C. Une vendeuse ferme son stand à la fin du marché. D. Une cliente emballe les fruits pour un transport.","segments":[{"voice":"female","text":"Question 1."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. Une vendeuse étiquette des bocaux sur une étagère. B. Une cliente compare les fruits de deux paniers. C. Une vendeuse ferme son stand à la fin du marché. D. Une cliente emballe les fruits pour un transport."}],"audio":"q-01.mp3","audioSeconds":20.672,"slotSeconds":41,"image":"q-01.svg"},{"number":2,"kind":"image","question":"Quelle action voit-on ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"Le fermier examine une conduite d'irrigation entre des rangées de cultures.","transcript":"Question 2.\nRegardez l’image et écoutez les propositions.\nA. L'agriculteur nettoie une machine après la récolte. B. L'agriculteur charge des sacs de grains dans une camionnette. C. L'agriculteur vérifie un tuyau d'arrosage. D. L'agriculteur récolte des pommes dans un verger.","segments":[{"voice":"female","text":"Question 2."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. L'agriculteur nettoie une machine après la récolte. B. L'agriculteur charge des sacs de grains dans une camionnette. C. L'agriculteur vérifie un tuyau d'arrosage. D. L'agriculteur récolte des pommes dans un verger."}],"audio":"q-02.mp3","audioSeconds":20.544,"slotSeconds":41,"image":"q-02.svg"},{"number":3,"kind":"image","question":"Quelle action voit-on ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"Une personne dépose des pains sur une balance dans une cuisine associative.","transcript":"Question 3.\nRegardez l’image et écoutez les propositions.\nA. Un bénévole transporte des pains vers une table. B. Un bénévole prépare des affiches pour une collecte. C. Un bénévole range des plats dans un réfrigérateur. D. Un bénévole pèse du pain récupéré dans une boulangerie.","segments":[{"voice":"female","text":"Question 3."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. Un bénévole transporte des pains vers une table. B. Un bénévole prépare des affiches pour une collecte. C. Un bénévole range des plats dans un réfrigérateur. D. Un bénévole pèse du pain récupéré dans une boulangerie."}],"audio":"q-03.mp3","audioSeconds":20.288,"slotSeconds":41,"image":"q-03.svg"},{"number":4,"kind":"image","question":"Quelle action voit-on ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"Le cuisinier utilise une planche et un couteau pour préparer les légumes.","transcript":"Question 4.\nRegardez l’image et écoutez les propositions.\nA. Le cuisinier découpe des légumes sur un plan de travail. B. Le cuisinier lave des assiettes après le service. C. Le cuisinier range les ingrédients dans un placard. D. Le cuisinier apporte un plateau au comptoir.","segments":[{"voice":"female","text":"Question 4."},{"voice":"female","text":"Regardez l’image et écoutez les propositions."},{"voice":"female","text":"A. Le cuisinier découpe des légumes sur un plan de travail. B. Le cuisinier lave des assiettes après le service. C. Le cuisinier range les ingrédients dans un placard. D. Le cuisinier apporte un plateau au comptoir."}],"audio":"q-04.mp3","audioSeconds":20.033,"slotSeconds":41,"image":"q-04.svg"},{"number":5,"kind":"response","question":"Quelle réponse convient ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"B","explanation":"L'interlocuteur répond à la provenance des tomates.","transcript":"Question 5.\nCes tomates viennent-elles de votre exploitation ?\nA. Elles se conservent trois jours à température ambiante. B. Oui, nous les cultivons à quelques kilomètres d'ici. C. Elles seront disponibles à partir de vendredi. D. Elles coûtent deux euros cinquante le kilo.","segments":[{"voice":"female","text":"Question 5."},{"voice":"female","text":"Ces tomates viennent-elles de votre exploitation ?"},{"voice":"male","text":"A. Elles se conservent trois jours à température ambiante. B. Oui, nous les cultivons à quelques kilomètres d'ici. C. Elles seront disponibles à partir de vendredi. D. Elles coûtent deux euros cinquante le kilo."}],"audio":"q-05.mp3","audioSeconds":21.502,"slotSeconds":42},{"number":6,"kind":"response","question":"Quelle réponse convient ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"A","explanation":"La réponse indique comment effectuer la réservation du panier.","transcript":"Question 6.\nPuis-je réserver un panier de légumes pour samedi ?\nA. Oui, inscrivez votre nom avant jeudi soir. B. Oui, le marché ouvre plus tard samedi. C. Les paniers coûtent moins cher en été. D. Les légumes sont récoltés dès l'aube.","segments":[{"voice":"female","text":"Question 6."},{"voice":"male","text":"Puis-je réserver un panier de légumes pour samedi ?"},{"voice":"female","text":"A. Oui, inscrivez votre nom avant jeudi soir. B. Oui, le marché ouvre plus tard samedi. C. Les paniers coûtent moins cher en été. D. Les légumes sont récoltés dès l'aube."}],"audio":"q-06.mp3","audioSeconds":18.506,"slotSeconds":40},{"number":7,"kind":"response","question":"Quelle réponse convient ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"C","explanation":"La troisième proposition donne un conseil concret de conservation.","transcript":"Question 7.\nVous connaissez la meilleure façon de conserver ces herbes fraîches ?\nA. Le potager est situé derrière le bâtiment. B. La livraison arrive au marché dans une heure. C. Gardez-les au frais dans un linge légèrement humide. D. La récolte a commencé tôt ce matin.","segments":[{"voice":"female","text":"Question 7."},{"voice":"female","text":"Vous connaissez la meilleure façon de conserver ces herbes fraîches ?"},{"voice":"male","text":"A. Le potager est situé derrière le bâtiment. B. La livraison arrive au marché dans une heure. C. Gardez-les au frais dans un linge légèrement humide. D. La récolte a commencé tôt ce matin."}],"audio":"q-07.mp3","audioSeconds":20.817,"slotSeconds":42},{"number":8,"kind":"response","question":"Quelle réponse convient ?","options":["Proposition A","Proposition B","Proposition C","Proposition D"],"correct":"D","explanation":"L'interlocuteur confirme que la dégustation est incluse.","transcript":"Question 8.\nEst-ce que la dégustation de ce soir est comprise dans le billet ?\nA. Elle commence à dix-neuf heures en salle trois. B. Elle sera animée par deux producteurs régionaux. C. Elle proposera cinq recettes végétariennes différentes. D. Oui, l'entrée comprend la dégustation des produits.","segments":[{"voice":"female","text":"Question 8."},{"voice":"male","text":"Est-ce que la dégustation de ce soir est comprise dans le billet ?"},{"voice":"female","text":"A. Elle commence à dix-neuf heures en salle trois. B. Elle sera animée par deux producteurs régionaux. C. Elle proposera cinq recettes végétariennes différentes. D. Oui, l'entrée comprend la dégustation des produits."}],"audio":"q-08.mp3","audioSeconds":20.614,"slotSeconds":42},{"number":9,"kind":"announcement","question":"Quand la distribution des paniers aura-t-elle lieu ?","options":["Samedi, entre huit et dix heures.","Samedi, entre neuf et onze heures.","Dimanche, entre neuf et onze heures.","Dimanche, entre huit et dix heures."],"correct":"A","explanation":"La distribution est avancée et se tient samedi de huit à dix heures.","transcript":"Question 9.\nEn raison de la chaleur annoncée pour samedi, la distribution des paniers de légumes commencera une heure plus tôt que d'habitude. Les abonnés pourront récupérer leur commande de huit heures à dix heures au hangar du marché. Le lieu reste le même et les paniers non retirés seront conservés dans la chambre froide jusqu'à midi.\nQuand la distribution des paniers aura-t-elle lieu ?","segments":[{"voice":"female","text":"Question 9."},{"voice":"female","text":"En raison de la chaleur annoncée pour samedi, la distribution des paniers de légumes commencera une heure plus tôt que d'habitude. Les abonnés pourront récupérer leur commande de huit heures à dix heures au hangar du marché. Le lieu reste le même et les paniers non retirés seront conservés dans la chambre froide jusqu'à midi."},{"voice":"female","text":"Quand la distribution des paniers aura-t-elle lieu ?"}],"audio":"q-09.mp3","audioSeconds":22.274,"slotSeconds":44},{"number":10,"kind":"dialogue","question":"Pourquoi la restauratrice modifie-t-elle sa commande ?","options":["La cuisine préfère essayer de nouvelles recettes.","La quantité de courgettes disponible est insuffisante.","Le fournisseur a changé le prix des aubergines.","La livraison doit être déplacée au lendemain."],"correct":"B","explanation":"Le fournisseur ne peut livrer que dix kilos de courgettes au lieu de quinze.","transcript":"Question 10.\nBonjour, je vous ai commandé quinze kilos de courgettes pour demain.\nNous en avons seulement dix. Les dernières pluies ont retardé une partie de la récolte.\nDans ce cas, pouvez-vous compléter avec cinq kilos d'aubergines ? Je pourrai adapter le menu.\nOui, je vous livrerai les deux produits demain matin.\nTrès bien, je préviens la cuisine.\nPourquoi la restauratrice modifie-t-elle sa commande ?","segments":[{"voice":"female","text":"Question 10."},{"voice":"female","text":"Bonjour, je vous ai commandé quinze kilos de courgettes pour demain."},{"voice":"male","text":"Nous en avons seulement dix. Les dernières pluies ont retardé une partie de la récolte."},{"voice":"female","text":"Dans ce cas, pouvez-vous compléter avec cinq kilos d'aubergines ? Je pourrai adapter le menu."},{"voice":"male","text":"Oui, je vous livrerai les deux produits demain matin."},{"voice":"female","text":"Très bien, je préviens la cuisine."},{"voice":"female","text":"Pourquoi la restauratrice modifie-t-elle sa commande ?"}],"audio":"q-10.mp3","audioSeconds":26.665,"slotSeconds":48},{"number":11,"kind":"announcement","question":"Comment faut-il participer à l'atelier culinaire ?","options":["En téléphonant à la médiathèque vendredi.","En apportant son matériel de cuisine samedi.","En achetant des ingrédients avant samedi.","En remplissant un formulaire avant jeudi."],"correct":"D","explanation":"Une inscription avant jeudi sur formulaire est indispensable.","transcript":"Question 11.\nL'association Saveurs du quartier propose samedi un atelier consacré aux plats de saison. Les participants doivent réserver leur place avant jeudi sur le formulaire disponible à la médiathèque. Les ingrédients seront fournis. Il n'est pas nécessaire d'apporter de matériel, mais un tablier personnel reste conseillé.\nComment faut-il participer à l'atelier culinaire ?","segments":[{"voice":"female","text":"Question 11."},{"voice":"male","text":"L'association Saveurs du quartier propose samedi un atelier consacré aux plats de saison. Les participants doivent réserver leur place avant jeudi sur le formulaire disponible à la médiathèque. Les ingrédients seront fournis. Il n'est pas nécessaire d'apporter de matériel, mais un tablier personnel reste conseillé."},{"voice":"female","text":"Comment faut-il participer à l'atelier culinaire ?"}],"audio":"q-11.mp3","audioSeconds":25.49,"slotSeconds":48},{"number":12,"kind":"dialogue","question":"Quel arrangement est convenu pour la livraison ?","options":["Reporter la commande à la semaine prochaine.","Livrer les fromages dimanche par l'entrée principale.","Déposer les produits samedi soir dans un local réfrigéré.","Laisser les produits devant la boutique jusqu'au matin."],"correct":"C","explanation":"La livraison est avancée à samedi soir avec conservation immédiate au froid.","transcript":"Question 12.\nNotre camion ne pourra pas accéder au marché pendant la course cycliste de dimanche.\nLe quai de déchargement sera encore libre samedi soir. Pouvez-vous avancer la livraison des fromages ?\nOui, vers dix-huit heures trente. Mais il faudra les placer immédiatement au frais.\nNous aurons une personne sur place pour ouvrir la chambre froide.\nQuel arrangement est convenu pour la livraison ?","segments":[{"voice":"female","text":"Question 12."},{"voice":"male","text":"Notre camion ne pourra pas accéder au marché pendant la course cycliste de dimanche."},{"voice":"female","text":"Le quai de déchargement sera encore libre samedi soir. Pouvez-vous avancer la livraison des fromages ?"},{"voice":"male","text":"Oui, vers dix-huit heures trente. Mais il faudra les placer immédiatement au frais."},{"voice":"female","text":"Nous aurons une personne sur place pour ouvrir la chambre froide."},{"voice":"female","text":"Quel arrangement est convenu pour la livraison ?"}],"audio":"q-12.mp3","audioSeconds":26.874,"slotSeconds":49},{"number":13,"kind":"announcement","question":"Quelle précaution est demandée aux vendeurs ?","options":["Conserver les produits fragiles dans leur équipement froid.","Livrer la marchandise au centre de contrôle mardi soir.","Déplacer tous les aliments vers les étals de fruits secs.","Fermer définitivement les stands de produits frais."],"correct":"A","explanation":"Les vendeurs doivent conserver les produits réfrigérés dans les équipements appropriés.","transcript":"Question 13.\nLe marché couvert informe les commerçants qu'un contrôle de température sera réalisé mercredi matin sur les installations de réfrigération. Les produits sensibles doivent rester dans leur équipement habituel jusqu'au passage de l'agent. Les étals de fruits secs et d'objets artisanaux ne sont pas concernés.\nQuelle précaution est demandée aux vendeurs ?","segments":[{"voice":"female","text":"Question 13."},{"voice":"female","text":"Le marché couvert informe les commerçants qu'un contrôle de température sera réalisé mercredi matin sur les installations de réfrigération. Les produits sensibles doivent rester dans leur équipement habituel jusqu'au passage de l'agent. Les étals de fruits secs et d'objets artisanaux ne sont pas concernés."},{"voice":"female","text":"Quelle précaution est demandée aux vendeurs ?"}],"audio":"q-13.mp3","audioSeconds":22.401,"slotSeconds":45},{"number":14,"kind":"dialogue","question":"Pourquoi le menu du jour a-t-il changé ?","options":["Les clients ont demandé un plat entièrement sans légumes.","Le restaurant souhaite supprimer toutes les recettes anciennes.","Une erreur de livraison a conduit à utiliser d'autres ingrédients.","Le cuisinier a reçu une nouvelle consigne concernant les portions."],"correct":"C","explanation":"Les ingrédients reçus ne correspondent pas à la commande prévue.","transcript":"Question 14.\nJe pensais que vous serviez un gratin de pommes de terre aujourd'hui.\nC'était prévu, mais notre livraison est arrivée avec des patates douces à la place.\nVous avez changé la recette ?\nOui, nous en avons fait une soupe avec des carottes et des lentilles. Les allergies sont indiquées sur l'ardoise.\nD'accord, je vais essayer cette soupe.\nPourquoi le menu du jour a-t-il changé ?","segments":[{"voice":"female","text":"Question 14."},{"voice":"male","text":"Je pensais que vous serviez un gratin de pommes de terre aujourd'hui."},{"voice":"female","text":"C'était prévu, mais notre livraison est arrivée avec des patates douces à la place."},{"voice":"male","text":"Vous avez changé la recette ?"},{"voice":"female","text":"Oui, nous en avons fait une soupe avec des carottes et des lentilles. Les allergies sont indiquées sur l'ardoise."},{"voice":"male","text":"D'accord, je vais essayer cette soupe."},{"voice":"female","text":"Pourquoi le menu du jour a-t-il changé ?"}],"audio":"q-14.mp3","audioSeconds":26.451,"slotSeconds":49},{"number":15,"kind":"radio-news","question":"Quel obstacle les producteurs rencontrent-ils avec la nouvelle coopérative ?","options":["Le groupement ne dispose d'aucun véhicule de livraison.","Les producteurs doivent désormais livrer leurs produits individuellement.","Les cantines scolaires refusent les produits de la région.","Les quantités récoltées varient et compliquent les engagements."],"correct":"D","explanation":"L'incertitude sur les récoltes rend difficile le respect des volumes convenus.","transcript":"Question 15.\nUn groupement de producteurs du Lot a ouvert une plateforme commune pour livrer les cantines scolaires. Le système doit réduire les déplacements séparés de chaque ferme. Pourtant, plusieurs maraîchers soulignent que leurs récoltes ne sont pas toujours disponibles aux quantités et dates prévues. La coopérative envisage des commandes plus souples afin de limiter les annulations de dernière minute.\nQuel obstacle les producteurs rencontrent-ils avec la nouvelle coopérative ?","segments":[{"voice":"female","text":"Question 15."},{"voice":"female","text":"Un groupement de producteurs du Lot a ouvert une plateforme commune pour livrer les cantines scolaires. Le système doit réduire les déplacements séparés de chaque ferme. Pourtant, plusieurs maraîchers soulignent que leurs récoltes ne sont pas toujours disponibles aux quantités et dates prévues. La coopérative envisage des commandes plus souples afin de limiter les annulations de dernière minute."},{"voice":"female","text":"Quel obstacle les producteurs rencontrent-ils avec la nouvelle coopérative ?"}],"audio":"q-15.mp3","audioSeconds":28.462,"slotSeconds":51},{"number":16,"kind":"dialogue","question":"Pourquoi la personne chargée de la cantine demande-t-elle un autre jour ?","options":["Le responsable souhaite tester un nouveau fournisseur.","La cuisine ne pourra pas recevoir de produits mardi.","Le prix des pommes sera modifié mardi.","La cantine recevra une autre commande mercredi."],"correct":"B","explanation":"La cantine ferme mardi pour entretien et fixe une livraison mercredi tôt.","transcript":"Question 16.\nLe fournisseur de pommes me propose une livraison mardi, mais notre cuisine sera fermée pour entretien.\nNous pourrions venir mercredi matin, avant la préparation du déjeuner.\nMercredi, oui, à condition d'arriver avant huit heures.\nJe note sept heures trente. Il faudra quelqu'un pour signer le bordereau.\nLe chef sera présent.\nPourquoi la personne chargée de la cantine demande-t-elle un autre jour ?","segments":[{"voice":"female","text":"Question 16."},{"voice":"female","text":"Le fournisseur de pommes me propose une livraison mardi, mais notre cuisine sera fermée pour entretien."},{"voice":"male","text":"Nous pourrions venir mercredi matin, avant la préparation du déjeuner."},{"voice":"female","text":"Mercredi, oui, à condition d'arriver avant huit heures."},{"voice":"male","text":"Je note sept heures trente. Il faudra quelqu'un pour signer le bordereau."},{"voice":"female","text":"Le chef sera présent."},{"voice":"female","text":"Pourquoi la personne chargée de la cantine demande-t-elle un autre jour ?"}],"audio":"q-16.mp3","audioSeconds":27.258,"slotSeconds":51},{"number":17,"kind":"announcement","question":"Qu'est-ce qui sera récupéré par la collecte ?","options":["Tous les déchets alimentaires destinés au compost.","Les marchandises livrées le jeudi matin.","Les invendus encore propres à la consommation.","Les emballages réutilisables des commerçants."],"correct":"C","explanation":"La collecte alimentaire concerne les invendus encore consommables.","transcript":"Question 17.\nLa collecte contre le gaspillage se tiendra jeudi à la fermeture du marché. Les bénévoles reprendront les fruits et légumes encore consommables qui n'ont pas trouvé preneur. Les produits abîmés ou non conformes à la consommation seront orientés vers la filière de compostage. Les commerçants doivent séparer les deux catégories avant l'arrivée des équipes.\nQu'est-ce qui sera récupéré par la collecte ?","segments":[{"voice":"female","text":"Question 17."},{"voice":"male","text":"La collecte contre le gaspillage se tiendra jeudi à la fermeture du marché. Les bénévoles reprendront les fruits et légumes encore consommables qui n'ont pas trouvé preneur. Les produits abîmés ou non conformes à la consommation seront orientés vers la filière de compostage. Les commerçants doivent séparer les deux catégories avant l'arrivée des équipes."},{"voice":"female","text":"Qu'est-ce qui sera récupéré par la collecte ?"}],"audio":"q-17.mp3","audioSeconds":26.186,"slotSeconds":50},{"number":18,"kind":"telephone","question":"Pourquoi le client souhaite-t-il parler au responsable ?","options":["Il souhaite souscrire un abonnement contenant davantage de lait.","Il cherche à modifier le nombre de paniers par semaine.","Il demande de déplacer sa livraison vers une autre adresse.","Il a reçu une commande incompatible avec sa formule."],"correct":"D","explanation":"Le panier livré ne respecte pas le choix sans produits laitiers.","transcript":"Question 18.\nBonjour, j'ai reçu un panier qui contenait des produits laitiers, alors que mon abonnement indique une formule sans lait.\nJe vois bien votre choix dans le dossier. Je vais prévenir l'équipe de préparation et vérifier le colis de remplacement.\nPouvez-vous me rappeler avant la prochaine livraison ? Je veux m'assurer que l'erreur ne se reproduira pas.\nBien sûr, notre responsable vous contactera aujourd'hui.\nPourquoi le client souhaite-t-il parler au responsable ?","segments":[{"voice":"female","text":"Question 18."},{"voice":"male","text":"Bonjour, j'ai reçu un panier qui contenait des produits laitiers, alors que mon abonnement indique une formule sans lait."},{"voice":"female","text":"Je vois bien votre choix dans le dossier. Je vais prévenir l'équipe de préparation et vérifier le colis de remplacement."},{"voice":"male","text":"Pouvez-vous me rappeler avant la prochaine livraison ? Je veux m'assurer que l'erreur ne se reproduira pas."},{"voice":"female","text":"Bien sûr, notre responsable vous contactera aujourd'hui."},{"voice":"female","text":"Pourquoi le client souhaite-t-il parler au responsable ?"}],"audio":"q-18.mp3","audioSeconds":29.794,"slotSeconds":53},{"number":19,"kind":"announcement","question":"Pourquoi le marché limite-t-il le nombre de visiteurs par groupe ?","options":["Pour garantir des échanges et des déplacements sans gêne.","Pour sélectionner uniquement les familles ayant des enfants.","Pour réserver les visites aux salariés de la ferme.","Pour diminuer le nombre de démonstrations prévues."],"correct":"A","explanation":"La limitation facilite l'écoute et la circulation près des animaux.","transcript":"Question 19.\nLors des visites de la ferme pédagogique, les groupes ne dépasseront pas huit personnes. Les explications auront lieu à proximité des animaux, dans des espaces parfois étroits. Ce nombre réduit permettra aux visiteurs d'entendre les consignes, de poser des questions et de circuler sans gêner les soins apportés aux bêtes.\nPourquoi le marché limite-t-il le nombre de visiteurs par groupe ?","segments":[{"voice":"female","text":"Question 19."},{"voice":"female","text":"Lors des visites de la ferme pédagogique, les groupes ne dépasseront pas huit personnes. Les explications auront lieu à proximité des animaux, dans des espaces parfois étroits. Ce nombre réduit permettra aux visiteurs d'entendre les consignes, de poser des questions et de circuler sans gêner les soins apportés aux bêtes."},{"voice":"female","text":"Pourquoi le marché limite-t-il le nombre de visiteurs par groupe ?"}],"audio":"q-19.mp3","audioSeconds":23.783,"slotSeconds":47},{"number":20,"kind":"dialogue","question":"Qu'est-ce qui préoccupe le responsable du restaurant ?","options":["La difficulté de former le personnel aux nouvelles recettes.","L'impossibilité d'assurer les mêmes produits toute l'année.","Le prix des aliments importés pendant l'hiver.","La nécessité de remplacer immédiatement le matériel de cuisine."],"correct":"B","explanation":"Il craint de ne pas disposer des mêmes légumes en toute saison.","transcript":"Question 20.\nNous pourrions acheter tous nos légumes au producteur voisin. Son offre est intéressante.\nC'est possible, mais il faut tenir compte des périodes où certaines variétés ne poussent pas.\nJustement. Je ne veux pas promettre les mêmes plats toute l'année si les récoltes sont irrégulières.\nNous pouvons établir des menus qui changent selon les saisons et prévoir des substitutions.\nQu'est-ce qui préoccupe le responsable du restaurant ?","segments":[{"voice":"female","text":"Question 20."},{"voice":"male","text":"Nous pourrions acheter tous nos légumes au producteur voisin. Son offre est intéressante."},{"voice":"female","text":"C'est possible, mais il faut tenir compte des périodes où certaines variétés ne poussent pas."},{"voice":"male","text":"Justement. Je ne veux pas promettre les mêmes plats toute l'année si les récoltes sont irrégulières."},{"voice":"female","text":"Nous pouvons établir des menus qui changent selon les saisons et prévoir des substitutions."},{"voice":"female","text":"Qu'est-ce qui préoccupe le responsable du restaurant ?"}],"audio":"q-20.mp3","audioSeconds":28.029,"slotSeconds":52},{"number":21,"kind":"announcement","question":"Pourquoi les bénévoles doivent-ils communiquer leur disponibilité ?","options":["Pour organiser les équipes de collecte selon les horaires.","Pour limiter le nombre de familles aidées par la banque.","Pour choisir les commerces qui pourront ouvrir plus tard.","Pour désigner les personnes chargées d'acheter les produits."],"correct":"A","explanation":"Les horaires des bénévoles permettent d'assurer une collecte dans chaque marché.","transcript":"Question 21.\nLa banque alimentaire organise samedi une récupération des invendus dans trois marchés. Les quantités ne seront connues qu'à la fermeture et les véhicules devront partir rapidement. Merci aux bénévoles de préciser s'ils peuvent aider en fin d'après-midi ou en début de soirée. Nous répartirons les équipes selon les véhicules et les horaires, afin de ne pas laisser certains marchés sans collecte.\nPourquoi les bénévoles doivent-ils communiquer leur disponibilité ?","segments":[{"voice":"female","text":"Question 21."},{"voice":"female","text":"La banque alimentaire organise samedi une récupération des invendus dans trois marchés. Les quantités ne seront connues qu'à la fermeture et les véhicules devront partir rapidement. Merci aux bénévoles de préciser s'ils peuvent aider en fin d'après-midi ou en début de soirée. Nous répartirons les équipes selon les véhicules et les horaires, afin de ne pas laisser certains marchés sans collecte."},{"voice":"female","text":"Pourquoi les bénévoles doivent-ils communiquer leur disponibilité ?"}],"audio":"q-21.mp3","audioSeconds":26.987,"slotSeconds":51},{"number":22,"kind":"interview","question":"Quel bénéfice la maraîchère attribue-t-elle surtout au marché collectif ?","options":["La garantie d'un revenu identique chaque semaine.","La possibilité d'obtenir toutes les variétés en hiver.","La compréhension mutuelle entre producteurs et clients.","La disparition des contraintes liées aux récoltes."],"correct":"C","explanation":"Elle insiste sur le dialogue et une meilleure compréhension des réalités agricoles.","transcript":"Question 22.\nVous participez depuis trois ans à un marché géré par les producteurs. Est-ce d'abord une manière de vendre davantage ?\nC'est important, mais l'essentiel est que nous discutons directement avec les habitants. Ils comprennent mieux pourquoi certaines récoltes sont plus petites ou moins belles. De notre côté, nous découvrons leurs habitudes et leurs contraintes. Cela nous aide à organiser les paniers et évite des malentendus lorsque les produits changent au fil de l'année. La relation compte autant que la transaction.\nQuel bénéfice la maraîchère attribue-t-elle surtout au marché collectif ?","segments":[{"voice":"female","text":"Question 22."},{"voice":"male","text":"Vous participez depuis trois ans à un marché géré par les producteurs. Est-ce d'abord une manière de vendre davantage ?"},{"voice":"female","text":"C'est important, mais l'essentiel est que nous discutons directement avec les habitants. Ils comprennent mieux pourquoi certaines récoltes sont plus petites ou moins belles. De notre côté, nous découvrons leurs habitudes et leurs contraintes. Cela nous aide à organiser les paniers et évite des malentendus lorsque les produits changent au fil de l'année. La relation compte autant que la transaction."},{"voice":"female","text":"Quel bénéfice la maraîchère attribue-t-elle surtout au marché collectif ?"}],"audio":"q-22.mp3","audioSeconds":35.585,"slotSeconds":60},{"number":23,"kind":"panel-discussion","question":"Quel accord se dessine pour les menus scolaires ?","options":["Confier la gestion complète des repas aux seuls agriculteurs.","Tester une offre saisonnière en mesurant ses effets.","Signer des contrats annuels identiques sans modifier les menus.","Remplacer immédiatement tous les ingrédients des cantines."],"correct":"B","explanation":"Les participants proposent une expérimentation saisonnière avec suivi du gaspillage et des réactions.","transcript":"Question 23.\nNous discutons de la place des aliments locaux dans les cantines.\nPour les producteurs, des contrats réguliers faciliteraient les investissements.\nDu côté des cuisines, nous devons prévoir des recettes qui acceptent des quantités variables.\nEt les parents veulent des repas équilibrés et un coût maîtrisé.\nNous pourrions tester un calendrier saisonnier sur un trimestre, avec deux produits locaux chaque semaine.\nD'accord, si les équipes évaluent aussi les restes et les réactions des élèves.\nQuel accord se dessine pour les menus scolaires ?","segments":[{"voice":"female","text":"Question 23."},{"voice":"female","text":"Nous discutons de la place des aliments locaux dans les cantines."},{"voice":"male","text":"Pour les producteurs, des contrats réguliers faciliteraient les investissements."},{"voice":"female","text":"Du côté des cuisines, nous devons prévoir des recettes qui acceptent des quantités variables."},{"voice":"male","text":"Et les parents veulent des repas équilibrés et un coût maîtrisé."},{"voice":"female","text":"Nous pourrions tester un calendrier saisonnier sur un trimestre, avec deux produits locaux chaque semaine."},{"voice":"male","text":"D'accord, si les équipes évaluent aussi les restes et les réactions des élèves."},{"voice":"female","text":"Quel accord se dessine pour les menus scolaires ?"}],"audio":"q-23.mp3","audioSeconds":34.886,"slotSeconds":59},{"number":24,"kind":"interview","question":"Quelle limite l'économiste relève-t-elle dans les statistiques ?","options":["Les prix enregistrés ne correspondaient pas aux tarifs habituels.","La période d'observation comprenait plusieurs saisons de récolte.","Les produits présentés au festival étaient de qualité très variable.","Les répondants étaient déjà particulièrement sensibles aux produits locaux."],"correct":"D","explanation":"L'échantillon sélectionné pendant un festival spécialisé n'est pas représentatif.","transcript":"Question 24.\nUne enquête indique que les consommateurs achètent plus volontiers des produits locaux. Peut-on en conclure que leurs habitudes ont changé ?\nNous devons nuancer. Les personnes interrogées avaient répondu à un questionnaire diffusé lors d'un festival consacré à l'agriculture régionale. Elles étaient donc probablement plus intéressées par ces sujets que la population générale. Il faut comparer ces déclarations aux achats réels et interroger aussi ceux qui ne fréquentent pas ce type d'événement. Dire ce que l'on préfère ne signifie pas toujours agir en conséquence.\nQuelle limite l'économiste relève-t-elle dans les statistiques ?","segments":[{"voice":"female","text":"Question 24."},{"voice":"male","text":"Une enquête indique que les consommateurs achètent plus volontiers des produits locaux. Peut-on en conclure que leurs habitudes ont changé ?"},{"voice":"female","text":"Nous devons nuancer. Les personnes interrogées avaient répondu à un questionnaire diffusé lors d'un festival consacré à l'agriculture régionale. Elles étaient donc probablement plus intéressées par ces sujets que la population générale. Il faut comparer ces déclarations aux achats réels et interroger aussi ceux qui ne fréquentent pas ce type d'événement. Dire ce que l'on préfère ne signifie pas toujours agir en conséquence."},{"voice":"female","text":"Quelle limite l'économiste relève-t-elle dans les statistiques ?"}],"audio":"q-24.mp3","audioSeconds":36.835,"slotSeconds":61},{"number":25,"kind":"television-report","question":"Quel problème le reportage souligne-t-il ?","options":["La disparition progressive de tous les marchés de village.","Le refus des restaurateurs d'acheter des produits de montagne.","La difficulté de regrouper des livraisons assez efficaces.","L'interdiction de transporter les aliments en camion."],"correct":"C","explanation":"La faible densité des trajets rend certaines livraisons peu efficaces.","transcript":"Question 25.\nDans les Alpes, une coopérative propose aux restaurateurs des produits issus de petites exploitations. Les commandes sont centralisées pour éviter que chaque producteur effectue une longue tournée.\nMais certains villages restent loin des axes de transport, explique le coordinateur. Un camion peu rempli peut annuler une partie des gains économiques et environnementaux.\nLa coopérative teste désormais des points de regroupement et des jours de livraison communs, sans promettre que toutes les exploitations pourront être desservies chaque semaine.\nQuel problème le reportage souligne-t-il ?","segments":[{"voice":"female","text":"Question 25."},{"voice":"female","text":"Dans les Alpes, une coopérative propose aux restaurateurs des produits issus de petites exploitations. Les commandes sont centralisées pour éviter que chaque producteur effectue une longue tournée."},{"voice":"male","text":"Mais certains villages restent loin des axes de transport, explique le coordinateur. Un camion peu rempli peut annuler une partie des gains économiques et environnementaux."},{"voice":"female","text":"La coopérative teste désormais des points de regroupement et des jours de livraison communs, sans promettre que toutes les exploitations pourront être desservies chaque semaine."},{"voice":"female","text":"Quel problème le reportage souligne-t-il ?"}],"audio":"q-25.mp3","audioSeconds":37.032,"slotSeconds":63},{"number":26,"kind":"interview","question":"Pourquoi l'agronome refuse-t-elle une solution d'irrigation identique partout ?","options":["Parce que les terrains et les plantes demandent des réglages différents.","Parce que les cultures ont toujours des besoins identiques.","Parce que l'arrosage manuel est systématiquement moins coûteux.","Parce que les capteurs ne fonctionnent que sous serre."],"correct":"A","explanation":"L'agronome explique que sol et cultures doivent être pris en compte dans les réglages.","transcript":"Question 26.\nDes capteurs peuvent désormais déclencher automatiquement l'arrosage. Pourquoi certains producteurs restent-ils prudents ?\nLes mesures sont utiles, mais un sol argileux retient l'eau autrement qu'un sol sableux. Les cultures, l'exposition au vent et la profondeur des racines comptent aussi. Si l'on applique le même seuil à toutes les parcelles, on risque d'arroser trop ou pas assez. Nous recommandons de vérifier les données avec des observations de terrain et d'ajuster les réglages selon les besoins réels, plutôt que d'abandonner toute décision aux capteurs.\nPourquoi l'agronome refuse-t-elle une solution d'irrigation identique partout ?","segments":[{"voice":"female","text":"Question 26."},{"voice":"male","text":"Des capteurs peuvent désormais déclencher automatiquement l'arrosage. Pourquoi certains producteurs restent-ils prudents ?"},{"voice":"female","text":"Les mesures sont utiles, mais un sol argileux retient l'eau autrement qu'un sol sableux. Les cultures, l'exposition au vent et la profondeur des racines comptent aussi. Si l'on applique le même seuil à toutes les parcelles, on risque d'arroser trop ou pas assez. Nous recommandons de vérifier les données avec des observations de terrain et d'ajuster les réglages selon les besoins réels, plutôt que d'abandonner toute décision aux capteurs."},{"voice":"female","text":"Pourquoi l'agronome refuse-t-elle une solution d'irrigation identique partout ?"}],"audio":"q-26.mp3","audioSeconds":39.016,"slotSeconds":65},{"number":27,"kind":"dialogue","question":"Quelle décision prend le responsable des achats ?","options":["Utiliser exclusivement les nouvelles pommes dans tous les desserts.","Augmenter le prix des desserts pour garder les mêmes ingrédients.","Renoncer à tout achat de pommes cette semaine.","Répartir les achats selon la préparation prévue."],"correct":"D","explanation":"Ils choisissent deux fournisseurs selon les usages culinaires.","transcript":"Question 27.\nLe fournisseur nous propose des pommes moins chères, mais leur calibre est plus petit que d'habitude.\nCela peut convenir aux compotes, mais pas aux desserts qui exigent de grandes tranches.\nAlors commandons une partie du lot pour les compotes et gardons notre fournisseur habituel pour le reste.\nJe vérifierai les quantités nécessaires pour chaque recette.\nQuelle décision prend le responsable des achats ?","segments":[{"voice":"female","text":"Question 27."},{"voice":"male","text":"Le fournisseur nous propose des pommes moins chères, mais leur calibre est plus petit que d'habitude."},{"voice":"female","text":"Cela peut convenir aux compotes, mais pas aux desserts qui exigent de grandes tranches."},{"voice":"male","text":"Alors commandons une partie du lot pour les compotes et gardons notre fournisseur habituel pour le reste."},{"voice":"female","text":"Je vérifierai les quantités nécessaires pour chaque recette."},{"voice":"female","text":"Quelle décision prend le responsable des achats ?"}],"audio":"q-27.mp3","audioSeconds":26.56,"slotSeconds":52},{"number":28,"kind":"interview","question":"Quelle erreur le chercheur identifie-t-il dans la préparation du projet ?","options":["Les commerçants ont refusé de fournir des produits depuis le lancement.","Le système a été conçu sans étudier suffisamment les circuits de redistribution.","La chambre froide était trop petite pour tous les produits.","Les bénévoles avaient demandé davantage de matériel avant le projet."],"correct":"B","explanation":"Le projet a privilégié la capacité de stockage sans résoudre les problèmes de circulation et tri.","transcript":"Question 28.\nVotre association a acheté une grande chambre froide pour réduire le gaspillage. Pourtant, les pertes n'ont pas diminué. Pourquoi ?\nNous avions évalué la capacité de stockage avant d'observer la façon dont les denrées circulaient réellement. Certaines collectes arrivaient trop tard pour être redistribuées le lendemain; d'autres produits nécessitaient un tri rapide. Le matériel était performant, mais l'organisation ne suivait pas. Nous devons maintenant revoir les horaires de collecte, la formation des bénévoles et la traçabilité. Acheter une machine n'a pas remplacé le travail d'analyse des besoins.\nQuelle erreur le chercheur identifie-t-il dans la préparation du projet ?","segments":[{"voice":"female","text":"Question 28."},{"voice":"male","text":"Votre association a acheté une grande chambre froide pour réduire le gaspillage. Pourtant, les pertes n'ont pas diminué. Pourquoi ?"},{"voice":"female","text":"Nous avions évalué la capacité de stockage avant d'observer la façon dont les denrées circulaient réellement. Certaines collectes arrivaient trop tard pour être redistribuées le lendemain; d'autres produits nécessitaient un tri rapide. Le matériel était performant, mais l'organisation ne suivait pas. Nous devons maintenant revoir les horaires de collecte, la formation des bénévoles et la traçabilité. Acheter une machine n'a pas remplacé le travail d'analyse des besoins."},{"voice":"female","text":"Quelle erreur le chercheur identifie-t-il dans la préparation du projet ?"}],"audio":"q-28.mp3","audioSeconds":41.228,"slotSeconds":67},{"number":29,"kind":"debate","question":"Quel désaccord oppose principalement les deux invités ?","options":["Le choix des plats servis aux élèves en période de vacances.","L'intérêt des activités pédagogiques organisées par les fermes.","La nécessité de réduire le gaspillage dans les cuisines collectives.","Le niveau d'obligation à imposer dans l'approvisionnement local."],"correct":"D","explanation":"Ils divergent sur la rigidité d'une proportion locale obligatoire.","transcript":"Question 29.\nFaut-il encourager toutes les cantines à utiliser uniquement des produits locaux ?\nCela renforcerait les emplois agricoles de la région et raccourcirait certains transports.\nMais les producteurs locaux ne peuvent pas forcément fournir toutes les variétés ni toutes les quantités toute l'année. Il faut éviter que l'obligation crée des pénuries ou des coûts trop élevés.\nJe ne réclame pas un changement en une semaine. Nous pouvons fixer des objectifs progressifs.\nNous sommes d'accord pour soutenir la région, mais pas sur la rigidité du pourcentage imposé.\nQuel désaccord oppose principalement les deux invités ?","segments":[{"voice":"female","text":"Question 29."},{"voice":"female","text":"Faut-il encourager toutes les cantines à utiliser uniquement des produits locaux ?"},{"voice":"male","text":"Cela renforcerait les emplois agricoles de la région et raccourcirait certains transports."},{"voice":"female","text":"Mais les producteurs locaux ne peuvent pas forcément fournir toutes les variétés ni toutes les quantités toute l'année. Il faut éviter que l'obligation crée des pénuries ou des coûts trop élevés."},{"voice":"male","text":"Je ne réclame pas un changement en une semaine. Nous pouvons fixer des objectifs progressifs."},{"voice":"female","text":"Nous sommes d'accord pour soutenir la région, mais pas sur la rigidité du pourcentage imposé."},{"voice":"female","text":"Quel désaccord oppose principalement les deux invités ?"}],"audio":"q-29.mp3","audioSeconds":38.763,"slotSeconds":64},{"number":30,"kind":"interview","question":"Quelle conception du patrimoine alimentaire défend la spécialiste ?","options":["Préserver les savoir-faire tout en acceptant certaines adaptations.","Supprimer les ingrédients traditionnels dans toutes les recettes.","Remplacer les cuisines régionales par des recettes internationales.","Conserver une seule version officielle de chaque préparation."],"correct":"A","explanation":"La spécialiste valorise la transmission avec possibilité d'évolution.","transcript":"Question 30.\nVous travaillez sur la préservation des recettes régionales. Faut-il les reproduire exactement ?\nLes recettes racontent une histoire, mais elles n'ont jamais été totalement immobiles. Les ingrédients disponibles changent, les familles adaptent leurs gestes et les techniques évoluent. Il est important de documenter les méthodes anciennes et de transmettre les savoir-faire, tout en laissant les cuisiniers répondre aux goûts et aux contraintes actuels. Une tradition vivante n'est pas une pièce de musée qu'on ne pourrait plus toucher.\nQuelle conception du patrimoine alimentaire défend la spécialiste ?","segments":[{"voice":"female","text":"Question 30."},{"voice":"male","text":"Vous travaillez sur la préservation des recettes régionales. Faut-il les reproduire exactement ?"},{"voice":"female","text":"Les recettes racontent une histoire, mais elles n'ont jamais été totalement immobiles. Les ingrédients disponibles changent, les familles adaptent leurs gestes et les techniques évoluent. Il est important de documenter les méthodes anciennes et de transmettre les savoir-faire, tout en laissant les cuisiniers répondre aux goûts et aux contraintes actuels. Une tradition vivante n'est pas une pièce de musée qu'on ne pourrait plus toucher."},{"voice":"female","text":"Quelle conception du patrimoine alimentaire défend la spécialiste ?"}],"audio":"q-30.mp3","audioSeconds":36.828,"slotSeconds":63},{"number":31,"kind":"academic-monologue","question":"Quelle conclusion sur les pratiques agricoles la conférencière met-elle en avant ?","options":["Privilégier les récoltes les plus récentes au détriment du passé.","Isoler les effets des autres changements avant de conclure.","Attribuer les rendements à l'outil dès la première saison.","Comparer uniquement les parcelles ayant le meilleur sol."],"correct":"B","explanation":"La conférencière recommande de contrôler les autres facteurs influençant les rendements.","transcript":"Question 31.\nDans plusieurs exploitations, les rendements ont augmenté après l'adoption d'un nouvel outil d'analyse des sols. Il serait tentant d'attribuer cette progression uniquement à l'outil. Pourtant, les agriculteurs ont aussi modifié les rotations et bénéficié de pluies plus régulières. Pour déterminer ce que le dispositif apporte réellement, nous devons comparer des parcelles semblables, suivre les résultats plusieurs saisons et tenir compte des autres changements. Une amélioration constatée après une innovation ne constitue pas, à elle seule, une preuve de causalité.\nQuelle conclusion sur les pratiques agricoles la conférencière met-elle en avant ?","segments":[{"voice":"female","text":"Question 31."},{"voice":"female","text":"Dans plusieurs exploitations, les rendements ont augmenté après l'adoption d'un nouvel outil d'analyse des sols. Il serait tentant d'attribuer cette progression uniquement à l'outil. Pourtant, les agriculteurs ont aussi modifié les rotations et bénéficié de pluies plus régulières. Pour déterminer ce que le dispositif apporte réellement, nous devons comparer des parcelles semblables, suivre les résultats plusieurs saisons et tenir compte des autres changements. Une amélioration constatée après une innovation ne constitue pas, à elle seule, une preuve de causalité."},{"voice":"female","text":"Quelle conclusion sur les pratiques agricoles la conférencière met-elle en avant ?"}],"audio":"q-31.mp3","audioSeconds":39.201,"slotSeconds":66},{"number":32,"kind":"interview","question":"Comment le spécialiste souhaite-t-il communiquer les prévisions de récolte ?","options":["En communiquant un volume fixe sans expliquer sa méthode.","En donnant uniquement la prévision la plus optimiste.","En révisant les estimations et en précisant leurs incertitudes.","En attendant la fin de la moisson avant tout échange."],"correct":"C","explanation":"Il préconise une fourchette explicitée et des mises à jour.","transcript":"Question 32.\nVous prévoyez la production de blé de l'année prochaine. Peut-on annoncer un chiffre précis aux coopératives ?\nNous pouvons présenter une fourchette, mais une température extrême ou une maladie des plantes pourrait changer les résultats. Il faut expliquer les hypothèses de départ et mettre les prévisions à jour quand de nouvelles observations arrivent. Les acheteurs ont besoin d'anticiper, certes, mais il serait irresponsable de traiter une estimation comme une quantité déjà récoltée.\nComment le spécialiste souhaite-t-il communiquer les prévisions de récolte ?","segments":[{"voice":"female","text":"Question 32."},{"voice":"male","text":"Vous prévoyez la production de blé de l'année prochaine. Peut-on annoncer un chiffre précis aux coopératives ?"},{"voice":"female","text":"Nous pouvons présenter une fourchette, mais une température extrême ou une maladie des plantes pourrait changer les résultats. Il faut expliquer les hypothèses de départ et mettre les prévisions à jour quand de nouvelles observations arrivent. Les acheteurs ont besoin d'anticiper, certes, mais il serait irresponsable de traiter une estimation comme une quantité déjà récoltée."},{"voice":"female","text":"Comment le spécialiste souhaite-t-il communiquer les prévisions de récolte ?"}],"audio":"q-32.mp3","audioSeconds":33.478,"slotSeconds":60},{"number":33,"kind":"commentary","question":"Quelle critique la chroniqueuse adresse-t-elle à l'indicateur présenté ?","options":["Le poids des déchets est une mesure inutile dans tous les contextes.","La revente à bas prix devrait être interdite dans tous les magasins.","Les associations ne devraient jamais recevoir les produits invendus.","La baisse des déchets pesés ne prouve pas que tous les aliments ont été consommés."],"correct":"D","explanation":"Elle souligne la différence entre produits retirés des déchets et produits réellement consommés.","transcript":"Question 33.\nUne enseigne annonce avoir réduit de moitié le gaspillage dans ses magasins. C'est encourageant, mais ce chiffre repose uniquement sur le poids des déchets jetés. Certains produits ont désormais été donnés à des associations, ce qui constitue un progrès; d'autres sont simplement revendus à bas prix alors qu'ils ne seront pas forcément consommés. Il faut suivre la destination réelle des aliments et les quantités effectivement utilisées. Déplacer un produit hors de la poubelle ne signifie pas toujours qu'il a évité le gaspillage.\nQuelle critique la chroniqueuse adresse-t-elle à l'indicateur présenté ?","segments":[{"voice":"female","text":"Question 33."},{"voice":"female","text":"Une enseigne annonce avoir réduit de moitié le gaspillage dans ses magasins. C'est encourageant, mais ce chiffre repose uniquement sur le poids des déchets jetés. Certains produits ont désormais été donnés à des associations, ce qui constitue un progrès; d'autres sont simplement revendus à bas prix alors qu'ils ne seront pas forcément consommés. Il faut suivre la destination réelle des aliments et les quantités effectivement utilisées. Déplacer un produit hors de la poubelle ne signifie pas toujours qu'il a évité le gaspillage."},{"voice":"female","text":"Quelle critique la chroniqueuse adresse-t-elle à l'indicateur présenté ?"}],"audio":"q-33.mp3","audioSeconds":34.383,"slotSeconds":61},{"number":34,"kind":"roundtable","question":"Quel compromis est finalement proposé ?","options":["Prévoir des contrats saisonniers avec des substitutions convenues.","Supprimer les engagements écrits entre cantines et producteurs.","Imposer une recette fixe chaque semaine pendant toute l'année.","Accepter toutes les livraisons, même si elles sont inutilisables."],"correct":"A","explanation":"Ils s'entendent sur des contrats souples prévoyant des substitutions.","transcript":"Question 34.\nUne table ronde réunit des agriculteurs, des responsables de cantine et des consommateurs.\nNous aimerions des commandes stables pour planifier nos semis.\nLes cantines doivent tenir leur budget, mais les enfants veulent aussi des repas variés.\nSi une récolte échoue, nous avons besoin de pouvoir proposer une autre variété sans être pénalisés.\nNous pourrions conclure des contrats saisonniers avec une liste de substitutions acceptées à l'avance.\nÀ condition de suivre aussi les quantités réellement consommées.\nD'accord, testons cette formule sur un trimestre.\nQuel compromis est finalement proposé ?","segments":[{"voice":"female","text":"Question 34."},{"voice":"female","text":"Une table ronde réunit des agriculteurs, des responsables de cantine et des consommateurs."},{"voice":"male","text":"Nous aimerions des commandes stables pour planifier nos semis."},{"voice":"female","text":"Les cantines doivent tenir leur budget, mais les enfants veulent aussi des repas variés."},{"voice":"male","text":"Si une récolte échoue, nous avons besoin de pouvoir proposer une autre variété sans être pénalisés."},{"voice":"female","text":"Nous pourrions conclure des contrats saisonniers avec une liste de substitutions acceptées à l'avance."},{"voice":"male","text":"À condition de suivre aussi les quantités réellement consommées."},{"voice":"female","text":"D'accord, testons cette formule sur un trimestre."},{"voice":"female","text":"Quel compromis est finalement proposé ?"}],"audio":"q-34.mp3","audioSeconds":39.833,"slotSeconds":66},{"number":35,"kind":"interview","question":"Quelle idée l'ingénieure remet-elle en question ?","options":["Tous les emballages devraient être supprimés immédiatement.","Les contenants réutilisables conviennent seulement aux produits secs.","La réutilisation garantit toujours un bilan environnemental supérieur.","Le lavage n'influence jamais les impacts environnementaux."],"correct":"C","explanation":"Elle conteste la supériorité environnementale automatique du réemploi, sans bilan complet.","transcript":"Question 35.\nLes nouveaux emballages réutilisables semblent très écologiques. Pourtant, vous demandez une évaluation plus complète. Pourquoi ?\nIl faut mesurer leur durée de vie, le nombre réel de réutilisations, les transports nécessaires au retour et l'eau utilisée pour le lavage. Un contenant peut être excellent s'il circule longtemps près de son lieu d'utilisation, mais beaucoup moins intéressant s'il parcourt des centaines de kilomètres après chaque livraison. L'étiquette « réutilisable » ne suffit donc pas à décrire son impact.\nQuelle idée l'ingénieure remet-elle en question ?","segments":[{"voice":"female","text":"Question 35."},{"voice":"male","text":"Les nouveaux emballages réutilisables semblent très écologiques. Pourtant, vous demandez une évaluation plus complète. Pourquoi ?"},{"voice":"female","text":"Il faut mesurer leur durée de vie, le nombre réel de réutilisations, les transports nécessaires au retour et l'eau utilisée pour le lavage. Un contenant peut être excellent s'il circule longtemps près de son lieu d'utilisation, mais beaucoup moins intéressant s'il parcourt des centaines de kilomètres après chaque livraison. L'étiquette « réutilisable » ne suffit donc pas à décrire son impact."},{"voice":"female","text":"Quelle idée l'ingénieure remet-elle en question ?"}],"audio":"q-35.mp3","audioSeconds":36.34,"slotSeconds":64},{"number":36,"kind":"interview","question":"À quelle condition les habitants profitent-ils réellement du jardin partagé ?","options":["Lorsque les récoltes sont vendues à un tarif commun.","Lorsque des formes variées de participation sont réellement possibles.","Lorsque tous les membres travaillent le même nombre d'heures.","Lorsque seuls les membres les plus expérimentés prennent les décisions."],"correct":"B","explanation":"La participation doit être ouverte et adaptée aux différentes contraintes.","transcript":"Question 36.\nLe jardin communautaire est très fréquenté. Est-ce suffisant pour dire qu'il favorise la solidarité ?\nPas nécessairement. Certaines personnes n'osent pas prendre la parole ou ne peuvent venir aux heures habituelles. Nous devons rendre les décisions transparentes, prévoir des tâches adaptées et permettre à chacun de participer sans devoir justifier ses contraintes. Si quelques membres décident de tout et les autres exécutent, le lieu peut rester agréable mais ne crée pas une véritable entraide.\nÀ quelle condition les habitants profitent-ils réellement du jardin partagé ?","segments":[{"voice":"female","text":"Question 36."},{"voice":"male","text":"Le jardin communautaire est très fréquenté. Est-ce suffisant pour dire qu'il favorise la solidarité ?"},{"voice":"female","text":"Pas nécessairement. Certaines personnes n'osent pas prendre la parole ou ne peuvent venir aux heures habituelles. Nous devons rendre les décisions transparentes, prévoir des tâches adaptées et permettre à chacun de participer sans devoir justifier ses contraintes. Si quelques membres décident de tout et les autres exécutent, le lieu peut rester agréable mais ne crée pas une véritable entraide."},{"voice":"female","text":"À quelle condition les habitants profitent-ils réellement du jardin partagé ?"}],"audio":"q-36.mp3","audioSeconds":36.601,"slotSeconds":64},{"number":37,"kind":"interview","question":"Pourquoi l'historienne conserve-t-elle des témoignages contradictoires ?","options":["Parce que la mémoire individuelle remplace avantageusement toute preuve écrite.","Parce que les récits reflètent des expériences différentes à confronter aux archives.","Parce que les témoins doivent choisir une histoire commune pour l'exposition.","Parce que chaque souvenir contredit nécessairement les documents officiels."],"correct":"B","explanation":"Elle examine les divergences à la lumière des positions des témoins et des archives.","transcript":"Question 37.\nLes anciens producteurs ne racontent pas tous la même chose sur la fermeture de la conserverie. Comment traiter ces différences ?\nNous vérifions d'abord les faits dans les archives : dates, décisions et effectifs. Mais le responsable de l'usine, un saisonnier et un commerçant n'avaient pas la même place dans l'événement. Leurs souvenirs révèlent des inquiétudes et des intérêts différents. Les contradictions deviennent utiles lorsqu'on connaît le contexte des témoignages, sans renoncer à distinguer les faits établis des impressions.\nPourquoi l'historienne conserve-t-elle des témoignages contradictoires ?","segments":[{"voice":"female","text":"Question 37."},{"voice":"male","text":"Les anciens producteurs ne racontent pas tous la même chose sur la fermeture de la conserverie. Comment traiter ces différences ?"},{"voice":"female","text":"Nous vérifions d'abord les faits dans les archives : dates, décisions et effectifs. Mais le responsable de l'usine, un saisonnier et un commerçant n'avaient pas la même place dans l'événement. Leurs souvenirs révèlent des inquiétudes et des intérêts différents. Les contradictions deviennent utiles lorsqu'on connaît le contexte des témoignages, sans renoncer à distinguer les faits établis des impressions."},{"voice":"female","text":"Pourquoi l'historienne conserve-t-elle des témoignages contradictoires ?"}],"audio":"q-37.mp3","audioSeconds":36.543,"slotSeconds":64},{"number":38,"kind":"public-lecture","question":"Quel paradoxe le conférencier décrit-il ?","options":["Un marché local devient toujours moins connu lorsque les visiteurs augmentent.","Le succès des marchés empêche systématiquement les producteurs de vendre.","Les produits régionaux sont uniquement destinés aux touristes dès leur création.","Une destination touristique peut perdre ce qui faisait sa valeur pour les habitants."],"correct":"D","explanation":"L'affluence peut transformer le marché au détriment de la population locale.","transcript":"Question 38.\nPromouvoir une destination pour ses produits du terroir peut attirer un grand nombre de visiteurs. Mais si le succès transforme les marchés en lieux destinés presque uniquement aux touristes, les habitants risquent de perdre l'accès aux produits et aux prix qui faisaient la réputation du lieu. Les producteurs peuvent aussi être poussés à privilégier des volumes et des présentations adaptés aux visiteurs plutôt que leurs clients habituels. Il faut donc distinguer le succès commercial immédiat de la capacité du marché à continuer de servir la communauté locale.\nQuel paradoxe le conférencier décrit-il ?","segments":[{"voice":"female","text":"Question 38."},{"voice":"male","text":"Promouvoir une destination pour ses produits du terroir peut attirer un grand nombre de visiteurs. Mais si le succès transforme les marchés en lieux destinés presque uniquement aux touristes, les habitants risquent de perdre l'accès aux produits et aux prix qui faisaient la réputation du lieu. Les producteurs peuvent aussi être poussés à privilégier des volumes et des présentations adaptés aux visiteurs plutôt que leurs clients habituels. Il faut donc distinguer le succès commercial immédiat de la capacité du marché à continuer de servir la communauté locale."},{"voice":"female","text":"Quel paradoxe le conférencier décrit-il ?"}],"audio":"q-38.mp3","audioSeconds":37.553,"slotSeconds":65},{"number":39,"kind":"interview","question":"Quelle démarche l'économiste conseille-t-elle pour pérenniser la cuisine associative ?","options":["Évaluer les coûts et organiser les ressources avant de s'étendre.","Réduire la qualité des ingrédients pour développer plus rapidement.","Multiplier les repas sans modifier les financements ni les horaires.","Confier toutes les tâches aux bénévoles les plus expérimentés."],"correct":"A","explanation":"Elle veut établir un modèle durable avant de le reproduire.","transcript":"Question 39.\nVotre cuisine partagée sert désormais beaucoup de repas. Pourquoi ne pas reproduire exactement son organisation actuelle dans d'autres quartiers ?\nParce qu'elle dépend encore d'un local prêté gratuitement et de bénévoles présents presque tous les jours. Nous devons d'abord connaître le coût réel des repas, répartir équitablement le travail et former des personnes capables de remplacer l'équipe de départ. Nous pouvons ensuite adapter le modèle à d'autres lieux, mais seulement si sa gestion reste soutenable. La popularité des premières semaines ne paiera pas à elle seule les charges régulières.\nQuelle démarche l'économiste conseille-t-elle pour pérenniser la cuisine associative ?","segments":[{"voice":"female","text":"Question 39."},{"voice":"male","text":"Votre cuisine partagée sert désormais beaucoup de repas. Pourquoi ne pas reproduire exactement son organisation actuelle dans d'autres quartiers ?"},{"voice":"female","text":"Parce qu'elle dépend encore d'un local prêté gratuitement et de bénévoles présents presque tous les jours. Nous devons d'abord connaître le coût réel des repas, répartir équitablement le travail et former des personnes capables de remplacer l'équipe de départ. Nous pouvons ensuite adapter le modèle à d'autres lieux, mais seulement si sa gestion reste soutenable. La popularité des premières semaines ne paiera pas à elle seule les charges régulières."},{"voice":"female","text":"Quelle démarche l'économiste conseille-t-elle pour pérenniser la cuisine associative ?"}],"audio":"q-39.mp3","audioSeconds":40.107,"slotSeconds":68}]}$paper06v2$::jsonb)
